"""Build the package long description with absolute repository links."""

from __future__ import annotations

import argparse
from pathlib import Path

from .build_wiki import ROOT, rewrite_markdown

OUTPUT = ROOT / "PYPI_README.md"
REPOSITORY_BLOB = "https://github.com/thekaveh/NNx/blob/main/"
REPOSITORY_RAW = "https://raw.githubusercontent.com/thekaveh/NNx/main/"


def render() -> str:
    source = ROOT / "README.md"
    source_map: dict[Path, str] = {}
    for path in ROOT.rglob("*"):
        if ".git" in path.parts or ".venv" in path.parts or "generated" in path.parts:
            continue
        relative = path.relative_to(ROOT).as_posix()
        if path.is_dir():
            source_map[path.resolve()] = "https://github.com/thekaveh/NNx/tree/main/" + relative
            continue
        prefix = (
            REPOSITORY_RAW
            if path.suffix.lower() in {".gif", ".jpeg", ".jpg", ".png", ".svg", ".webp"}
            else REPOSITORY_BLOB
        )
        source_map[path.resolve()] = prefix + relative
    return rewrite_markdown(source, source.read_text(encoding="utf-8"), source_map, surface="site")


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    rendered = render()
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != rendered:
            raise SystemExit("PYPI_README.md is stale; run python -m scripts.docs.build_pypi_readme")
        return
    OUTPUT.write_text(rendered, encoding="utf-8")


if __name__ == "__main__":
    main()

"""Render a portable Markdown API catalog from runtime signatures and docstrings."""

from __future__ import annotations

import argparse
import importlib
import inspect
import re
import sys
from enum import Enum
from pathlib import Path
from typing import Any, get_origin

ROOT = Path(__file__).resolve().parents[2]
CATALOG = ROOT / "scripts" / "docs" / "api_reference_catalog.txt"
OUTPUT = ROOT / "docs" / "api.md"
ENTRY = re.compile(r"^@api\s+(\S+?)(?:\s+members=([A-Za-z0-9_,]*))?\s*$")


def _doc_origin(value: Any) -> str | None:
    """The module of the class whose docstring ``inspect.getdoc`` would
    inherit for ``value``; ``None`` when ``value`` has its own."""
    if inspect.isclass(value):
        if value.__dict__.get("__doc__"):
            return None
        return next((base.__module__ for base in value.__mro__[1:] if base.__dict__.get("__doc__")), None)
    if getattr(value, "__doc__", None) and not isinstance(value, property):
        return None
    if isinstance(value, property):
        return None
    *owner_path, name = getattr(value, "__qualname__", "").split(".")
    owner: Any = sys.modules.get(getattr(value, "__module__", "") or "")
    for part in owner_path:
        owner = getattr(owner, part, None)
    if not inspect.isclass(owner):
        return None
    for base in owner.__mro__[1:]:
        attr = base.__dict__.get(name)
        if attr is not None and getattr(attr, "__doc__", None):
            return base.__module__
    return None


def _documentation(value: Any) -> tuple[str, str]:
    if get_origin(value) is not None:
        return "Public type alias.", ""
    if isinstance(value, Enum):
        return f"Enum value `{value.value}`.", ""
    if inspect.isclass(value) and issubclass(value, Enum):
        own_doc = value.__dict__.get("__doc__")
        if not own_doc or own_doc == "An enumeration.":
            names = ", ".join(f"`{name}`" for name in value.__members__)
            return f"Enum values: {names}.", ""
        doc = inspect.cleandoc(own_doc)
        paragraphs = re.split(r"\n\s*\n", doc, maxsplit=1)
        summary = " ".join(line.strip() for line in paragraphs[0].splitlines())
        details = paragraphs[1].strip() if len(paragraphs) == 2 else ""
        return summary, details
    if not callable(value) and not inspect.ismodule(value) and not isinstance(value, property):
        return "Exported value.", ""
    origin = _doc_origin(value)
    inherited_elsewhere = origin is not None and origin.split(".")[0] != "nnx"  # torch's nn.Module text, say
    doc = (None if inherited_elsewhere else inspect.getdoc(value)) or "No public description is currently available."
    paragraphs = re.split(r"\n\s*\n", doc, maxsplit=1)
    summary = " ".join(line.strip() for line in paragraphs[0].splitlines())
    details = paragraphs[1].strip() if len(paragraphs) == 2 else ""
    return summary, details


def _stable_annotation(annotation: Any) -> Any:
    if annotation is inspect.Signature.empty:
        return annotation
    if isinstance(annotation, str):
        return annotation
    forward_arg = getattr(annotation, "__forward_arg__", None)
    if isinstance(forward_arg, str):
        return forward_arg
    module = getattr(annotation, "__module__", None)
    qualname = getattr(annotation, "__qualname__", None)
    if isinstance(module, str) and isinstance(qualname, str):
        return f"{module}.{qualname}"
    return str(annotation).removeprefix("typing.")


def _signature(path: str, value: Any) -> str:
    if get_origin(value) is not None:
        return f"type alias {path}"
    if isinstance(value, Enum):
        return f"{path} = {value.value!r}"
    if inspect.isclass(value) and issubclass(value, Enum):
        return f"class {path}(Enum)"
    if inspect.ismodule(value):
        return f"module {path}"
    if isinstance(value, property):
        return f"property {path}"
    if not callable(value):
        if path == "nnx.__version__":
            # release-please bumps the marked line on its release branch (FIX-029),
            # where the installed metadata then reports the same version.
            return f"{path} = {value!r}  # x-release-please-version"
        return f"{path} = {value!r}"
    try:
        raw_signature = inspect.signature(value)
        parameters = [
            parameter.replace(annotation=_stable_annotation(parameter.annotation))
            for parameter in raw_signature.parameters.values()
        ]
        normalized = raw_signature.replace(
            parameters=parameters,
            return_annotation=_stable_annotation(raw_signature.return_annotation),
        )
        signature = re.sub(r"<class '([^']+)'>", r"\1", str(normalized))
    except (TypeError, ValueError):
        signature = ""
    prefix = "class " if inspect.isclass(value) else ""
    return f"{prefix}{path}{signature}"


def _locate(path: str) -> Any | None:
    parts = path.split(".")
    for module_end in range(len(parts), 0, -1):
        try:
            value: Any = importlib.import_module(".".join(parts[:module_end]))
        except ModuleNotFoundError:
            continue
        for attribute in parts[module_end:]:
            if not hasattr(value, attribute):
                break
            value = getattr(value, attribute)
        else:
            return value
    return None


def _class_members(value: type, documented: frozenset[type] = frozenset()) -> list[tuple[str, Any]]:
    members: list[tuple[str, Any]] = []
    enum_member_names: set[str] = set()
    if issubclass(value, Enum):
        enum_member_names = set(value.__members__)
        members.extend((name, member) for name, member in value.__members__.items())
    # Public members an undocumented nnx base contributes (JsonArtifact.save,
    # _Counted.coverage) are part of the class's API, so they render too; a
    # base with its own catalog entry (NNModel, Question) documents them there.
    # A documented base documents its own ancestry, so that part of the MRO is
    # skipped; an undocumented mixin beside it still renders. An optional-extra
    # stub (no huggingface_hub) never renders, so the output is the same either way.
    covered = {ancestor for base in value.__mro__[1:] if base in documented for ancestor in base.__mro__}
    owners = [value]
    for base in value.__mro__[1:]:
        if base in covered:
            continue
        if base.__module__.split(".")[0] == "nnx" and not base.__dict__.get("_optional_stub", False):
            owners.append(base)
    seen: set[str] = set()
    for owner in owners:
        for name, descriptor in owner.__dict__.items():
            if name.startswith("_") or name in enum_member_names or name in seen:
                continue
            seen.add(name)
            member = getattr(value, name)
            if callable(member) or isinstance(descriptor, property):
                members.append((name, descriptor if isinstance(descriptor, property) else member))
    return members


_ROLE = re.compile(r":[a-z]+:`(~?)([^`]+)`")


def _plain_roles(text: str) -> str:
    """Sphinx roles as Markdown code spans: ``:func:`nnx.lr_finder``` reads
    as `nnx.lr_finder` (and ``:class:`~nnx.models.ModelSpec``` as
    `ModelSpec`) on GitHub, the site and the wiki, which render no roles.
    An explicit title (``:meth:`title <target>```) keeps only the title."""

    def code(match: re.Match[str]) -> str:
        target = match.group(2)
        titled = re.fullmatch(r"(.*?)\s*<([^>]+)>", target)
        if titled:
            return f"`{titled.group(1)}`"
        return f"`{target.rsplit('.', 1)[-1] if match.group(1) else target}`"

    return _ROLE.sub(code, text)


def _render_entry(path: str, value: Any, *, heading_level: int = 4) -> list[str]:
    summary, details = _documentation(value)
    summary = _plain_roles(summary)  # the details are a literal text block
    rendered = [
        f"{'#' * heading_level} `{path}`",
        "",
        "```python",
        _signature(path, value),
        "```",
        "",
        summary,
        "",
    ]
    if details:
        rendered.extend(("**Details**", "", "```text", details, "```", ""))
    return rendered


def render() -> str:
    rendered: list[str] = []
    lines = CATALOG.read_text(encoding="utf-8").splitlines()
    documented = frozenset(
        value
        for value in (_locate(match.group(1)) for match in map(ENTRY.fullmatch, lines) if match is not None)
        if inspect.isclass(value)
    )
    for line in lines:
        match = ENTRY.fullmatch(line)
        if match is None:
            rendered.append(line)
            continue
        path = match.group(1)
        # "members=" with no names renders the entry alone (its members are documented elsewhere).
        explicit_members = None if match.group(2) is None else [name for name in match.group(2).split(",") if name]
        value = _locate(path)
        if value is None:
            raise ValueError(f"cannot resolve API catalog entry: {path}")
        rendered.extend(_render_entry(path, value))
        if explicit_members is not None:
            members = [(name, getattr(value, name)) for name in explicit_members]
        elif inspect.isclass(value):
            members = _class_members(value, documented)
        else:
            members = []
        for name, member in members:
            rendered.extend(_render_entry(f"{path}.{name}", member, heading_level=5))
    return "\n".join(rendered).rstrip() + "\n"


def build(*, check: bool = False) -> None:
    expected = render()
    if check:
        current = OUTPUT.read_text(encoding="utf-8") if OUTPUT.exists() else ""
        if current != expected:
            raise SystemExit("docs/api.md is stale; run python -m scripts.docs.build_api_reference")
        return
    OUTPUT.write_text(expected, encoding="utf-8")


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    build(check=args.check)


if __name__ == "__main__":
    main()

"""FIX-032: every workflow job runs on one pinned, tested runner image.

``ubuntu-latest`` moves to Ubuntu 26 from October 19, 2026 (and to later
images after that) without a change in this repository. Jobs name the image
they were verified on instead; moving to a new one is a deliberate change
(CONTRIBUTING §7.1), checked by this test and a CI run on the new label. A
package-mirror stall in an apt step fails within its own timeout instead of
consuming the whole job budget (#433 lost 30 minutes to one)."""

from __future__ import annotations

import re
from pathlib import Path

import pytest
import yaml

from tests._repo_files import repo_file

ROOT = Path(__file__).resolve().parents[1]
WORKFLOWS = sorted(repo_file(".github", "workflows").glob("*.y*ml"))
RUNNER = "ubuntu-26.04"
# FEAT-043: the one job that needs hardware no hosted image has (CUDA); it
# runs only on a registered self-hosted GPU runner, opted in by a variable.
SELF_HOSTED = {("docs.yml", "gpu-evidence"): ["self-hosted", "linux", "x64", "gpu"]}
APT_STEP_MINUTES = 5


def _jobs():
    for path in WORKFLOWS:
        for name, job in (yaml.safe_load(path.read_text(encoding="utf-8")).get("jobs") or {}).items():
            yield path.name, name, job


def test_the_workflows_exist():
    assert {path.name for path in WORKFLOWS} >= {
        "ci.yml",
        "docs.yml",
        "release.yml",
        "release-please.yml",
        "security.yml",
    }


@pytest.mark.parametrize(("workflow", "job_name", "job"), list(_jobs()), ids=lambda value: str(value)[:40])
def test_every_job_runs_on_the_pinned_image(workflow, job_name, job):
    if "uses" in job:  # a reusable-workflow call runs on the called workflow's image
        return
    expected = SELF_HOSTED.get((workflow, job_name), RUNNER)
    assert job.get("runs-on") == expected, f"{workflow}:{job_name} runs on {job.get('runs-on')!r}"


def test_the_self_hosted_jobs_exist_and_are_opt_in():
    jobs = {(workflow, name): job for workflow, name, job in _jobs()}
    for key in SELF_HOSTED:
        assert key in jobs, f"{key} is listed as self-hosted but does not exist"
        # skipped unless a GPU runner is registered, and never for a fork's pull request
        assert jobs[key]["if"].startswith("vars.NNX_GPU_RUNNER == 'true' && ")
        assert "head.repo.full_name == github.repository" in jobs[key]["if"]


def test_every_apt_step_has_its_own_short_timeout():
    apt_steps = [
        (workflow, job_name, step)
        for workflow, job_name, job in _jobs()
        for step in job.get("steps") or []
        if re.search(r"\bapt(-get)? ", str(step.get("run", "")))
    ]
    assert apt_steps, "the cairo runtime is installed with apt somewhere"
    for workflow, job_name, step in apt_steps:
        minutes = step.get("timeout-minutes")
        assert isinstance(minutes, int) and 0 < minutes <= APT_STEP_MINUTES, (workflow, job_name, step.get("name"))


def test_no_step_writes_under_tmp():
    """On ubuntu-26.04 /tmp is a size-capped tmpfs: the v0.4.0 release's
    artifact smoke test overflowed it installing torch ("Disk quota
    exceeded"). Steps use $RUNNER_TEMP, on the runner's work disk."""
    for workflow, job_name, job in _jobs():
        for step in job.get("steps") or []:
            assert "/tmp" not in str(step.get("run", "")), (workflow, job_name, step.get("name"))
